<script setup lang="ts">
import { computed, ref, watch, nextTick, onMounted, onBeforeUnmount, onUpdated } from 'vue';
import { mdiPlus, mdiMagnify, mdiArrowLeft, mdiArrowRight, mdiDownload, mdiMemory, mdiCheckCircleOutline, mdiAlertCircleOutline, mdiClose, mdiInformationOutline } from '@mdi/js';
import type { Database, InventoryPC, StockAllocation, StockRecord } from '../shared/types';
import { checkInstalledPC, pcAllocations, planDifferences, stockCounts, stockReadiness, overdueReservations, fleetPicklist, reorderSuggestions } from '../shared/inventory';
import { locationPath } from '../shared/installations';

const props = defineProps<{ db: Database; mode: 'stock' | 'pcs'; revision?: string }>();
const emit = defineEmits<{ reload: []; notify: [message: string]; editPc: [pc?: InventoryPC] }>();
const search = ref(''), tracking = ref('All tracking'), condition = ref('All conditions');
const stockId = ref(''), pcId = ref(''), tab = ref('parts'), stockTab = ref('allocations');
const draft = ref<StockRecord | null>(null), busy = ref(false);
const requestError=ref('');
const draftRevision = ref('');
const batch = ref<{componentId:string;tracking:'serialized'|'bulk';identities:string;quantity:number;location:string;supplier:string;purchaseOrder:string}|null>(null);
const serialization = ref<{stockId:string;identities:string;notes:string}|null>(null);
const commissioning = ref<{pcId:string;by:string;checks:string;notes:string;revision:string}|null>(null);
const decommissioning = ref<{pcId:string;disposition:StockRecord['condition'];location:string;notes:string;actor:string;revision:string}|null>(null);
const operation = ref<{
  action: 'reserve' | 'install' | 'install-reserved' | 'release' | 'remove' | 'configure';
  stockId: string; pcId: string; allocationId: string; quantity: number; plannedPlacementId: string;
  slotId: string; role: StockAllocation['role']; mount: StockAllocation['mount']; notes: string;
  owner:string;workOrder:string;dueAt:string;expiresAt:string;group:string;targetId:string;adapterPlacementId:string;controllerPlacementId:string;destinationLocation:string;disposition:StockRecord['condition'];
} | null>(null);
const adjustment = ref<{ stockId: string; quantity: number; notes: string } | null>(null);
const transfer = ref<{ stockId: string; quantity: number; assetTag: string; location: string; condition: StockRecord['condition']; notes: string } | null>(null);
const dialogs={draft,operation,adjustment,transfer,batch,serialization,commissioning,decommissioning};
const originals=new Map<string,string>();
const dialogFocus=new Map<string,HTMLElement>();
for(const [name,dialog] of Object.entries(dialogs))watch(dialog,(value,previous)=>{requestError.value='';if(value){originals.set(name,JSON.stringify(value));if(!previous&&document.activeElement instanceof HTMLElement)dialogFocus.set(name,document.activeElement);}else{originals.delete(name);const trigger=dialogFocus.get(name);dialogFocus.delete(name);void nextTick(()=>{if(trigger?.isConnected)trigger.focus();else document.getElementById('main-content')?.focus();});}},{flush:'sync'});
const unsaved=computed(()=>Object.entries(dialogs).some(([name,dialog])=>dialog.value&&JSON.stringify(dialog.value)!==originals.get(name)));
function closeDialog(name:keyof typeof dialogs){const dialog=dialogs[name];if(dialog.value&&JSON.stringify(dialog.value)!==originals.get(name)&&!window.confirm('Discard unsaved changes in this dialog?'))return;dialog.value=null;}
function confirmDiscard(){if(unsaved.value&&!window.confirm('Discard unsaved inventory changes?'))return false;for(const dialog of Object.values(dialogs))dialog.value=null;return true;}
function beforeUnload(event:BeforeUnloadEvent){if(unsaved.value){event.preventDefault();event.returnValue='';}}
function labelTableScrollRegions(){for(const table of Array.from(document.querySelectorAll<HTMLElement>('[data-inventory-table]'))){const nativeTable=table.querySelector('table');const name=table.getAttribute('data-table-name')||table.getAttribute('aria-label')||nativeTable?.getAttribute('aria-label')||'Inventory table';table.setAttribute('data-table-name',name);table.removeAttribute('aria-label');nativeTable?.setAttribute('aria-label',name);const wrapper=table.querySelector<HTMLElement>('.v-table__wrapper');if(wrapper){wrapper.setAttribute('tabindex','0');wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label',`${name}; scroll to view all columns`);}}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);labelTableScrollRegions();});onUpdated(labelTableScrollRegions);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
defineExpose({hasUnsavedChanges:()=>unsaved.value,confirmDiscard});
const part = (id: string) => props.db.components.find(c => c.id === id);
const pcName = (id: string) => props.db.pcs.find(p => p.id === id)?.name || id;
const pcLocation=(pc?:InventoryPC)=>pc?.installationLocationId?locationPath(pc.installationLocationId,props.db):pc?.location||'No location recorded';
const stockLabel = (s: StockRecord) => `${part(s.componentId)?.name || s.componentId} · ${s.serial || s.assetTag || s.id.slice(0, 8)} · ${stockCounts(s).available} available`;
const selectedStock = computed(() => props.db.inventory.find(s => s.id === stockId.value));
const selectedPC = computed(() => props.db.pcs.find(p => p.id === pcId.value));
const template = computed(() => props.db.configurations.find(c => c.id === selectedPC.value?.configurationId));
const allocations = computed(() => pcAllocations(pcId.value, props.db));
const readiness = computed(() => template.value ? stockReadiness(template.value, props.db, pcId.value) : []);
const differences = computed(() => selectedPC.value ? planDifferences(selectedPC.value, props.db) : []);
const installedReport = computed(() => selectedPC.value ? checkInstalledPC(selectedPC.value, props.db) : null);
const stocks = computed(() => props.db.inventory.filter(s =>
  `${part(s.componentId)?.name} ${s.serial} ${s.assetTag} ${s.location} ${s.allocations.filter(a=>a.state==='installed').map(a=>pcLocation(props.db.pcs.find(pc=>pc.id===a.pcId))).join(' ')}`.toLowerCase().includes(search.value.toLowerCase()) &&
  (tracking.value === 'All tracking' || s.tracking === tracking.value) && (condition.value === 'All conditions' || s.condition === condition.value)));
const pcs = computed(() => props.db.pcs.filter(p => `${p.name} ${p.serial} ${p.location} ${pcLocation(p)}`.toLowerCase().includes(search.value.toLowerCase())));
const totals = computed(() => props.db.inventory.reduce((n, s) => { const c = stockCounts(s); return { available: n.available + c.available, reserved: n.reserved + c.reserved, installed: n.installed + c.installed }; }, { available: 0, reserved: 0, installed: 0 }));
const movements = computed(() => props.db.inventory.flatMap(stock => stock.history.filter(e => e.pcId === pcId.value).map(event => ({ stock, event }))).sort((a, b) => b.event.at.localeCompare(a.event.at)));
const operationStock = computed(() => props.db.inventory.find(s => s.id === operation.value?.stockId));
const operationPC = computed(() => props.db.pcs.find(p => p.id === operation.value?.pcId));
const operationTemplate = computed(() => props.db.configurations.find(c => c.id === operationPC.value?.configurationId));
const operationHardware=computed(()=>operationPC.value?pcAllocations(operationPC.value.id,props.db).filter(r=>r.allocation.state==='installed'):[]);
const providers=computed(()=>{
  const actual=operationHardware.value.filter(r=>['Motherboard','Storage adapter'].includes(part(r.stock.componentId)?.category||''));
  const plans=(operationTemplate.value?.placements||[]).filter(p=>['Motherboard','Storage adapter'].includes(part(p.componentId)?.category||'')&&!actual.some(r=>r.allocation.plannedPlacementId===p.id));
  return [{title:'Automatic / not bound',value:'',category:''},...actual.map(r=>({title:`${part(r.stock.componentId)?.name} · ${r.stock.serial||r.stock.assetTag||'installed unit'}`,value:r.allocation.id,category:part(r.stock.componentId)?.category||''})),...plans.map(p=>({title:`${part(p.componentId)?.name} · planned`,value:p.id,category:part(p.componentId)?.category||''}))];
});
const slots=computed(()=>{const board=operationHardware.value.find(r=>part(r.stock.componentId)?.category==='Motherboard');const component=board?part(board.stock.componentId):part(operationTemplate.value?.placements.find(p=>part(p.componentId)?.category==='Motherboard')?.componentId||'');return [{title:'Automatic slot',value:''},...(component?.specs.slots||[]).map(s=>({title:`${s.id} · ${s.bus} x${s.physical} / ${s.lanes} lanes`,value:s.id}))];});
const driveTargets=computed(()=>{
  const provider=operation.value?.adapterPlacementId||operation.value?.controllerPlacementId;
  const providerRow=operationHardware.value.find(r=>r.allocation.id===provider);
  const providerPlan=operationTemplate.value?.placements.find(p=>p.id===provider);
  const components=providerRow?[part(providerRow.stock.componentId)]:providerPlan?[part(providerPlan.componentId)]:props.db.components.filter(c=>['Chassis','Motherboard'].includes(c.category)&&operationHardware.value.some(r=>r.stock.componentId===c.id));
  const items=components.flatMap(c=>(c?.specs.driveTargets||[]).filter(t=>operation.value?.mount==='auto'||t.mount===operation.value?.mount).map(t=>({title:`${c?.name} · ${t.id}`,value:t.id})));
  return [{title:'Automatic drive target',value:''},...items.filter((t,i)=>items.findIndex(x=>x.value===t.value)===i)];
});
const storageGroups=computed(()=>[{title:'Default storage group',value:''},...(operationPC.value?.buildSettings?.storage.groups||operationTemplate.value?.storage.groups||[]).map(g=>({title:g.name,value:g.id}))]);
const plannedLines = computed(() => operationTemplate.value?.placements.filter(p => p.componentId === operationStock.value?.componentId) || []);
const stockChoices = computed(() => props.db.inventory.filter(s => stockCounts(s).available > 0));
const operationAllocation = computed(() => operationStock.value?.allocations.find(a => a.id === operation.value?.allocationId));
const overdue = computed(()=>overdueReservations(props.db));
const picks = computed(()=>fleetPicklist(props.db));
const reorder = computed(()=>reorderSuggestions(props.db));
const operationLimit = computed(() => Math.min(32, operationAllocation.value?.quantity ?? (operationStock.value ? stockCounts(operationStock.value).available : 0)));
const isNewAllocation = computed(() => operation.value?.action === 'reserve' || operation.value?.action === 'install');
const showPlacement = computed(() => isNewAllocation.value || operation.value?.action === 'configure');
const operationTitles = { reserve: 'Reserve components', install: 'Record installation', 'install-reserved': 'Install reserved components', release: 'Release reservation', remove: 'Remove installed components', configure: 'Edit placement & reservation' };
const roleItems = [{ title: 'General component', value: 'general' }, { title: 'Boot drive', value: 'boot' }, { title: 'Data drive', value: 'data' }];
const mountItems = [{ title: 'Automatic / onboard', value: 'auto' }, { title: 'Internal bay', value: 'internal' }, { title: 'Front hot-swap bay', value: 'front-hot-swap' }, { title: 'Rear PCIe NVMe sled', value: 'rear-sled' }];

async function request(url: string, body: unknown, method = 'POST', revision?: string) {
  busy.value = true;
  requestError.value='';
  try {
    const response = await fetch(url, { method, headers: { 'Content-Type': 'application/json', ...(revision ? {'If-Match':revision} : {}) }, body: JSON.stringify(body) });
    const result = await response.json();
    if (!response.ok) throw Error(result.error || 'Request failed');
    emit('reload'); return true;
  } catch (error) { requestError.value=error instanceof Error?error.message:String(error);if(!Object.values(dialogs).some(dialog=>dialog.value))emit('notify', requestError.value);return false; }
  finally { busy.value = false; }
}
function editStock(stock?: StockRecord) {
  draftRevision.value=props.revision||'';
  draft.value = stock ? structuredClone(JSON.parse(JSON.stringify(stock))) : {
    id: crypto.randomUUID(), componentId: '', tracking: 'serialized', serial: '', assetTag: '',
    quantity: 1, location: '', condition: 'Serviceable', notes: '', allocations: [], history: [], supplier:'',purchaseOrder:'',reorderLevel:0,repairReference:'',supplierReturnReference:'',
  };
}
async function saveStock() {
  if (!draft.value) return;
  const record=draft.value;
  if (await request(`/api/inventory/${record.id}`, record, 'PUT', draftRevision.value)) {
    stockId.value = record.id; draft.value = null; emit('notify', 'Stock record saved to CSV.');
  }
}
function openAllocation(stock?: StockRecord, targetPC = '', componentId = '') {
  const candidate = stock || stockChoices.value.find(s => s.componentId === componentId);
  operation.value = {
    action: 'reserve', stockId: candidate?.id || '', pcId: targetPC, allocationId: '', quantity: 1,
    plannedPlacementId: '', role: part(candidate?.componentId || '')?.category === 'Drive' ? 'data' : 'general',
    mount: 'auto', slotId: '', notes: '',owner:'',workOrder:'',dueAt:'',expiresAt:'',group:'',targetId:'',adapterPlacementId:'',controllerPlacementId:'',destinationLocation:candidate?.location||'',disposition:'Serviceable',
  };
}
function resetPlacement() {
  if (!operation.value) return;
  operation.value.plannedPlacementId = ''; operation.value.slotId = ''; operation.value.mount = 'auto';
  operation.value.role = part(operationStock.value?.componentId || '')?.category === 'Drive' ? 'data' : 'general';
  operation.value.quantity = 1;
  operation.value.group='';operation.value.targetId='';operation.value.adapterPlacementId='';operation.value.controllerPlacementId='';
}
function applyPlannedPlacement() {
  const p = plannedLines.value.find(p => p.id === operation.value?.plannedPlacementId);
  if (p && operation.value) { operation.value.slotId = p.slotId; operation.value.role = p.role; operation.value.mount = p.mount; operation.value.group=p.group;operation.value.targetId=p.targetId||'';operation.value.adapterPlacementId=p.adapterPlacementId||'';operation.value.controllerPlacementId=p.controllerPlacementId||''; }
}
function openOperation(stock: StockRecord, allocation: StockAllocation, action: 'install-reserved'|'release'|'remove'|'configure') {
  operation.value = { owner:'',workOrder:'',dueAt:'',expiresAt:'',group:'',targetId:'',adapterPlacementId:'',controllerPlacementId:'', ...allocation, stockId: stock.id, allocationId: allocation.id, action, notes: action === 'configure' ? allocation.notes : '', destinationLocation:stock.location,disposition:stock.condition };
}
async function performOperation() {
  const op = operation.value;
  if (!op) return;
  if ([op.dueAt,op.expiresAt].some(value=>value&&!Number.isFinite(Date.parse(value)))) {requestError.value='Enter valid needed-by and expiry dates.';return;}
  const bindings={group:op.group,targetId:op.targetId,adapterPlacementId:op.adapterPlacementId,controllerPlacementId:op.controllerPlacementId};
  const metadata={owner:op.owner,workOrder:op.workOrder,dueAt:op.dueAt?new Date(op.dueAt).toISOString():'',expiresAt:op.expiresAt?new Date(op.expiresAt).toISOString():''};
  const body = isNewAllocation.value ? { action: op.action, pcId: op.pcId, quantity: op.quantity, plannedPlacementId: op.plannedPlacementId, slotId: op.slotId, role: op.role, mount: op.mount, notes: op.notes,...bindings,...metadata }
    : op.action === 'configure' ? { action: op.action, allocationId: op.allocationId, slotId: op.slotId, role: op.role, mount: op.mount, notes: op.notes,...bindings,...metadata }
    : { action: op.action, allocationId: op.allocationId, quantity: op.quantity, notes: op.notes,...(op.action==='remove'?{destinationLocation:op.destinationLocation,disposition:op.disposition}:{}) };
  if (await request(`/api/inventory/${op.stockId}/action`, body)) { operation.value = null; emit('notify', 'Inventory movement recorded.'); }
}
async function adjustCount() {
  const a = adjustment.value;
  if (a && await request(`/api/inventory/${a.stockId}/adjust`, { quantity: a.quantity, notes: a.notes })) { adjustment.value = null; emit('notify', 'Count adjustment recorded.'); }
}
async function transferLot() {
  const t = transfer.value;
  if (t && await request(`/api/inventory/${t.stockId}/transfer`, { quantity:t.quantity,assetTag:t.assetTag,location:t.location,condition:t.condition,notes:t.notes })) {
    transfer.value = null; emit('notify', 'Bulk transfer recorded; both lots saved together.');
  }
}
function openPC(pc: InventoryPC) { pcId.value = pc.id; tab.value = 'parts'; }
function installedCount(id: string) { return pcAllocations(id, props.db).filter(r => r.allocation.state === 'installed').reduce((n, r) => n + r.allocation.quantity, 0); }
function date(at: string) { return new Date(at).toLocaleString(); }
function identityRows(value:string) { return value.split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const [serial,assetTag='']=line.split(',').map(v=>v.trim());return {serial:serial!,assetTag};}); }
async function receiveBatch(){const b=batch.value;if(!b)return;const units=b.tracking==='serialized'?identityRows(b.identities):[{serial:'',assetTag:b.identities.trim()}];const records=units.map(unit=>({id:crypto.randomUUID(),componentId:b.componentId,tracking:b.tracking,serial:unit.serial,assetTag:unit.assetTag,quantity:b.tracking==='serialized'?1:b.quantity,location:b.location,condition:'Serviceable',supplier:b.supplier,purchaseOrder:b.purchaseOrder,reorderLevel:0,notes:'Batch receipt',allocations:[],history:[]}));if(await request('/api/inventory/batch',{records}))batch.value=null;}
async function serializeLot(){const s=serialization.value;if(s&&await request(`/api/inventory/${s.stockId}/serialize`,{units:identityRows(s.identities),notes:s.notes}))serialization.value=null;}
async function commission(){const c=commissioning.value;if(c&&await request(`/api/pcs/${c.pcId}/commission`,{by:c.by,checks:c.checks.split('\n').map(v=>v.trim()).filter(Boolean),notes:c.notes},'POST',c.revision))commissioning.value=null;}
async function decommission(){const c=decommissioning.value;if(c&&await request(`/api/pcs/${c.pcId}/decommission`,{disposition:c.disposition,location:c.location,notes:c.notes,actor:c.actor},'POST',c.revision))decommissioning.value=null;}
function scanIdentity(){const query=search.value.trim().toLowerCase();const found=props.db.inventory.find(s=>[s.serial,s.assetTag,s.id].some(v=>v.toLowerCase()===query));if(found)stockId.value=found.id;else emit('notify','No exact serial, asset tag or stock ID match.');}
function exportPicklist(){const cells=[['PC','Component','Planned','Installed','Reserved','Pick','Shortage'],...picks.value.map(r=>[r.pcName,part(r.componentId)?.name||r.componentId,r.required,r.installed,r.reserved,r.pick,r.shortage])];const csv=cells.map(row=>row.map(v=>{let cell=String(v);if(typeof v==='string'&&/^\s*[=+\-@]/.test(cell))cell="'"+cell;return '"'+cell.replaceAll('"','""')+'"';}).join(',')).join('\r\n');const href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=href;a.download='fleet-picklist.csv';a.click();URL.revokeObjectURL(href);}
function downloadSnapshot(snapshot:NonNullable<InventoryPC['snapshot']>,index:number){const href=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download=`commissioned-${selectedPC.value?.id}-revision-${index+1}.json`;a.click();URL.revokeObjectURL(href);}
</script>

<template>
  <template v-if="mode === 'stock' && !selectedStock">
    <div class="page-heading">
      <div><div class="eyebrow">FROM THE STOCKROOM TO THE SYSTEM</div><h1>Component inventory</h1><p>Individual serialized parts and bulk lots, with an accountable path into each PC.</p></div>
      <div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/export/inventory">Export CSV</v-btn><v-btn variant="outlined" @click="batch={componentId:'',tracking:'serialized',identities:'',quantity:1,location:'',supplier:'',purchaseOrder:''}">Batch receive</v-btn><v-btn color="primary" :prepend-icon="mdiPlus" @click="editStock()">Receive stock</v-btn></div>
    </div>
    <div class="overview-grid inventory-stats">
      <div class="stat-card"><div>Stock records</div><strong>{{db.inventory.length}}</strong><small>Units and bulk lots</small></div>
      <div class="stat-card"><div>Available units</div><strong>{{totals.available}}</strong><small>Serviceable, unallocated stock</small></div>
      <div class="stat-card"><div>Reserved units</div><strong>{{totals.reserved}}</strong><small>Held for registered PCs</small></div>
      <div class="stat-card"><div>Installed units</div><strong>{{totals.installed}}</strong><small>Recorded in built systems</small></div>
    </div>
    <div class="catalog-toolbar"><v-text-field v-model="search" label="Search inventory" placeholder="Scan serial, asset tag, or stock ID; press Enter" :prepend-inner-icon="mdiMagnify" hide-details @keydown.enter="scanIdentity" /><v-select v-model="tracking" label="Tracking" :items="['All tracking','serialized','bulk']" hide-details /><v-select v-model="condition" label="Condition" :items="['All conditions','Serviceable','Quarantined','Repair','Retired']" hide-details /></div>
    <section class="panel table-panel"><v-table data-inventory-table aria-label="Physical component stock"><thead><tr><th scope="col">COMPONENT / IDENTITY</th><th scope="col">TRACKING</th><th scope="col">STOCK / INSTALLED LOCATION</th><th scope="col">TOTAL</th><th scope="col">AVAILABLE</th><th scope="col">RESERVED</th><th scope="col">INSTALLED</th><th scope="col">CONDITION</th></tr></thead><tbody>
      <tr v-for="stock in stocks" :key="stock.id"><td><button class="table-name" @click="stockId=stock.id">{{part(stock.componentId)?.name}}</button><small>{{stock.serial ? `Serial: ${stock.serial}` : `Lot: ${stock.assetTag || stock.id.slice(0,8)}`}}<template v-if="stock.serial && stock.assetTag"> · {{stock.assetTag}}</template></small></td><td><span class="category-tag">{{stock.tracking}}</span></td><td>Home: {{stock.location || 'Not recorded'}}<small v-for="allocation in stock.allocations.filter(a=>a.state==='installed')" :key="allocation.id">{{pcName(allocation.pcId)}}: {{pcLocation(db.pcs.find(p=>p.id===allocation.pcId))}}</small></td><td>{{stock.quantity}}</td><td>{{stockCounts(stock).available}}</td><td>{{stockCounts(stock).reserved}}</td><td>{{stockCounts(stock).installed}}</td><td><span :class="['inventory-condition', stock.condition.toLowerCase()]">{{stock.condition}}</span></td></tr>
    </tbody></v-table><div v-if="!stocks.length" class="empty-state"><v-icon :icon="mdiMemory" size="32" /><h2>No physical stock recorded</h2><p>Receive serialized units or a bulk lot. Catalog entries describe part types; they do not create stock.</p><v-btn color="primary" class="mt-5" @click="editStock()">Receive stock</v-btn></div></section>
    <section v-if="overdue.length" class="panel inventory-differences"><h2>Overdue reservations</h2><p class="form-hint">Expiry highlights holds; stock remains reserved until explicitly released.</p><div v-for="{stock,allocation} in overdue" :key="allocation.id">{{part(stock.componentId)?.name}} · {{pcName(allocation.pcId)}} · {{allocation.quantity}} units · {{allocation.owner || 'No owner'}} · {{allocation.workOrder || 'No work order'}}<v-btn size="small" variant="text" @click="openOperation(stock,allocation,'release')">Review & release</v-btn></div></section>
    <section class="panel inventory-differences"><div class="section-head"><h2>Fleet picklist & shortages</h2><v-btn variant="outlined" size="small" @click="exportPicklist">Export picklist CSV</v-btn></div><p class="form-hint">Each free unit is assigned once across active PCs, in registration order. This preview does not reserve stock.</p><v-table data-inventory-table aria-label="Fleet picklist and shortages"><thead><tr><th scope="col">PC</th><th scope="col">Component</th><th scope="col">Pick</th><th scope="col">Shortage</th></tr></thead><tbody><tr v-for="row in picks.filter(r=>r.pick||r.shortage)" :key="row.pcId+row.componentId"><td>{{row.pcName}}</td><td>{{part(row.componentId)?.name}}</td><td>{{row.pick}}</td><td>{{row.shortage}}</td></tr></tbody></v-table></section>
    <section v-if="reorder.length" class="panel inventory-differences"><h2>Restock suggestions</h2><v-table data-inventory-table aria-label="Restock suggestions"><thead><tr><th scope="col">Component</th><th scope="col">Available</th><th scope="col">Minimum</th><th scope="col">Order</th><th scope="col">Supplier</th></tr></thead><tbody><tr v-for="row in reorder" :key="row.componentId"><td>{{row.name}}</td><td>{{row.available}}</td><td>{{row.reorderLevel}}</td><td>{{row.order}}</td><td>{{row.suppliers}}</td></tr></tbody></v-table></section>
    <div class="info-callout"><v-icon :icon="mdiInformationOutline" size="19" />Total includes reserved and installed units. Quarantined and retired records contribute no available stock. Each lot has one home stock location. Installed units follow their PC’s assigned site, room, bench or equipment system.</div>
  </template>

  <template v-else-if="mode === 'stock' && selectedStock">
    <div class="detail-back"><button @click="stockId=''"><v-icon :icon="mdiArrowLeft" size="16" />All component inventory</button><span>Saved to inventory.csv</span></div>
    <div class="page-heading"><div><div class="eyebrow">{{selectedStock.tracking.toUpperCase()}} STOCK RECORD</div><h1>{{part(selectedStock.componentId)?.name}}</h1><p>{{selectedStock.serial ? `Serial: ${selectedStock.serial}` : `Lot: ${selectedStock.assetTag || selectedStock.id.slice(0,8)}`}} · {{selectedStock.condition}} · {{selectedStock.location || 'No stock location'}}</p></div><div class="heading-actions"><v-btn variant="outlined" @click="editStock(selectedStock)">Edit record</v-btn><v-btn v-if="selectedStock.tracking==='bulk'" variant="outlined" @click="adjustment={stockId:selectedStock.id,quantity:selectedStock.quantity,notes:''}">Adjust count</v-btn><v-btn v-if="selectedStock.tracking==='bulk'" variant="outlined" :disabled="selectedStock.condition==='Retired'||!stockCounts(selectedStock).unallocated" @click="transfer={stockId:selectedStock.id,quantity:1,assetTag:'',location:selectedStock.location,condition:selectedStock.condition,notes:''}">Split / move lot</v-btn><v-btn v-if="selectedStock.tracking==='bulk'" variant="outlined" :disabled="!stockCounts(selectedStock).unallocated||selectedStock.condition==='Retired'" @click="serialization={stockId:selectedStock.id,identities:'',notes:''}">Assign serials</v-btn><v-btn color="primary" :prepend-icon="mdiPlus" :disabled="!stockCounts(selectedStock).available" @click="openAllocation(selectedStock)">Allocate stock</v-btn></div></div>
    <div class="port-summary stock-counts"><div><strong>{{selectedStock.quantity}}</strong><span>Total units</span></div><div><strong>{{stockCounts(selectedStock).available}}</strong><span>Available</span></div><div><strong>{{stockCounts(selectedStock).reserved}}</strong><span>Reserved</span></div><div><strong>{{stockCounts(selectedStock).installed}}</strong><span>Installed</span></div></div>
    <v-tabs v-model="stockTab" color="primary" class="content-tabs"><v-tab value="allocations">Allocations</v-tab><v-tab value="history">Movement history</v-tab></v-tabs>
    <section v-if="stockTab==='allocations'" class="panel table-panel"><v-table data-inventory-table aria-label="Stock allocations"><thead><tr><th scope="col">PC</th><th scope="col">STATE</th><th scope="col">QUANTITY</th><th scope="col">PLACEMENT</th><th scope="col">PHYSICAL LOCATION</th><th scope="col">ACTIONS</th></tr></thead><tbody><tr v-for="a in selectedStock.allocations" :key="a.id"><td>{{pcName(a.pcId)}}</td><td><span class="category-tag">{{a.state}}</span><small>{{a.owner}} {{a.workOrder}}</small><small v-if="a.expiresAt">Expires {{date(a.expiresAt)}}</small></td><td>{{a.quantity}}</td><td>{{a.role}} · {{a.mount}}<small>{{a.slotId || 'Auto slot / onboard'}}</small></td><td>{{a.state==='installed' ? pcLocation(db.pcs.find(p=>p.id===a.pcId)) : selectedStock.location || 'Stock location not recorded'}}</td><td><div class="inventory-row-actions"><v-btn v-if="a.state==='reserved'" size="small" variant="text" color="primary" @click="openOperation(selectedStock,a,'install-reserved')">Install</v-btn><v-btn size="small" variant="text" @click="openOperation(selectedStock,a,'configure')">{{a.state==='installed'?'Placement':'Reservation'}}</v-btn><v-btn size="small" variant="text" color="error" @click="openOperation(selectedStock,a,a.state==='reserved'?'release':'remove')">{{a.state==='reserved'?'Release':'Remove'}}</v-btn></div></td></tr></tbody></v-table><div v-if="!selectedStock.allocations.length" class="empty-state"><h2>No active allocations</h2><p>This stock is not reserved for or installed in a PC.</p></div></section>
    <section v-else class="panel table-panel"><v-table data-inventory-table aria-label="Stock movement history"><thead><tr><th scope="col">WHEN</th><th scope="col">ACTION</th><th scope="col">QUANTITY</th><th scope="col">PC</th><th scope="col">DETAILS / REASON</th></tr></thead><tbody><tr v-for="event in [...selectedStock.history].reverse()" :key="event.id"><td>{{date(event.at)}}</td><td>{{event.action}}</td><td>{{event.quantity}}</td><td>{{event.pcName || '—'}}</td><td class="movement-notes">{{event.notes || '—'}}</td></tr></tbody></v-table></section>
    <div class="bottom-note"><v-icon :icon="mdiInformationOutline" size="16" />{{selectedStock.notes || 'No stock notes recorded.'}} Stock records with movement history are retained; release/remove allocations before retiring a record.</div>
  </template>

  <template v-else-if="!selectedPC">
    <div class="page-heading"><div><div class="eyebrow">PLANNED, BUILT AND MAINTAINED</div><h1>PC inventory</h1><p>Track actual installed parts, reservations, build readiness and configuration drift.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="emit('editPc')">Register PC</v-btn></div>
    <v-text-field v-model="search" label="Search PCs" placeholder="Name, serial or location" :prepend-inner-icon="mdiMagnify" hide-details class="system-search" />
    <section class="panel table-panel"><v-table data-inventory-table aria-label="Registered PC inventory"><thead><tr><th scope="col">PC / ASSET NAME</th><th scope="col">SERIAL / LOCATION</th><th scope="col">PLANNED CONFIGURATION</th><th scope="col">INSTALLED</th><th scope="col">DRIFT</th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="pc in pcs" :key="pc.id"><td><button class="table-name" @click="openPC(pc)">{{pc.name}}</button></td><td>{{pc.serial || '—'}}<small>{{pcLocation(pc)}}</small></td><td>{{db.configurations.find(c=>c.id===pc.configurationId)?.name || 'Unassigned'}}</td><td>{{installedCount(pc.id)}} parts</td><td><span class="category-tag">{{installedCount(pc.id) ? `${planDifferences(pc,db).length} differences` : 'No install records'}}</span></td><td><v-btn variant="text" size="small" @click="emit('editPc',pc)">Edit PC</v-btn></td></tr></tbody></v-table><div v-if="!pcs.length" class="empty-state"><h2>No PCs found</h2><p>Register a PC, link a planned configuration, then allocate physical stock.</p></div></section>
  </template>

  <template v-else>
    <div class="detail-back"><button @click="pcId=''"><v-icon :icon="mdiArrowLeft" size="16" />All PCs</button><span>Recorded installed hardware</span></div>
    <div class="page-heading"><div><div class="eyebrow">BUILT SYSTEM</div><h1>{{selectedPC.name}}</h1><p>{{selectedPC.lifecycle || 'Planning'}} · {{selectedPC.serial || 'No serial'}} · {{pcLocation(selectedPC)}} · Planned: {{template?.name || 'Unassigned'}}</p></div><div class="heading-actions"><v-btn variant="outlined" @click="emit('editPc',selectedPC)">Edit PC & settings</v-btn><v-btn variant="outlined" :disabled="selectedPC.lifecycle==='Retired'" @click="commissioning={pcId:selectedPC.id,by:'',checks:'Hardware checked\nEquipment connection tested\nStorage and boot validated',notes:'',revision:revision||''}">Commission PC</v-btn><v-btn variant="outlined" color="error" @click="decommissioning={pcId:selectedPC.id,disposition:'Quarantined',location:'',notes:'',actor:'',revision:revision||''}">Decommission</v-btn><v-btn color="primary" :prepend-icon="mdiPlus" :disabled="!stockChoices.length" @click="openAllocation(undefined,selectedPC.id)">Allocate from stock</v-btn></div></div>
    <div class="installed-summary panel"><div><strong>{{installedCount(selectedPC.id)}} installed parts</strong><span>{{allocations.filter(r=>r.allocation.state==='reserved').reduce((n,r)=>n+r.allocation.quantity,0)}} reserved · {{differences.length}} differences from plan</span></div><div><strong>{{selectedPC.buildSettings ? 'Recorded equipment & storage settings' : 'Build settings not yet recorded'}}</strong><span>{{selectedPC.buildSettings ? `${db.systems.find(s=>s.id===selectedPC?.buildSettings?.systemId)?.name || 'No equipment linked'} · ${selectedPC.buildSettings.storage.raid} data layout` : 'Use Edit PC & settings to capture or enter them.'}}</span></div></div>
    <v-tabs v-model="tab" color="primary" class="content-tabs"><v-tab value="parts">Parts & reservations</v-tab><v-tab value="readiness">Build readiness</v-tab><v-tab value="report">Installed compatibility</v-tab><v-tab value="history">History</v-tab></v-tabs>
    <section v-if="tab==='parts'" class="panel table-panel"><v-table data-inventory-table aria-label="Installed parts and reservations"><thead><tr><th scope="col">ACTUAL COMPONENT / STOCK</th><th scope="col">QTY</th><th scope="col">STATE</th><th scope="col">RECORDED PLACEMENT</th><th scope="col">ACTIONS</th></tr></thead><tbody><tr v-for="{stock,allocation:a} in allocations" :key="a.id"><td>{{part(stock.componentId)?.name}}<small>{{stock.serial ? `Serial: ${stock.serial}` : `Lot: ${stock.assetTag || stock.id.slice(0,8)}`}} · {{stock.condition}}</small></td><td>{{a.quantity}}</td><td><span class="category-tag">{{a.state}}</span><small>{{a.owner}} {{a.workOrder}}</small><small v-if="a.expiresAt">Expires {{date(a.expiresAt)}}</small></td><td>{{a.role}} · {{a.mount}}<small>{{a.slotId || 'Auto / onboard'}} · target {{a.targetId || 'auto'}} · group {{a.group || 'default'}}</small></td><td><div class="inventory-row-actions"><v-btn v-if="a.state==='reserved'" variant="text" color="primary" size="small" @click="openOperation(stock,a,'install-reserved')">Install</v-btn><v-btn variant="text" size="small" @click="openOperation(stock,a,'configure')">{{a.state==='installed'?'Placement':'Reservation'}}</v-btn><v-btn variant="text" color="error" size="small" @click="openOperation(stock,a,a.state==='reserved'?'release':'remove')">{{a.state==='reserved'?'Release':'Remove'}}</v-btn></div></td></tr></tbody></v-table><div v-if="!allocations.length" class="empty-state"><h2>No physical parts allocated</h2><p>A linked configuration is a plan. Reserve or install stock to record this machine’s actual components.</p></div></section>
    <template v-if="tab==='readiness'">
      <section class="panel table-panel"><v-table data-inventory-table aria-label="PC build readiness"><thead><tr><th scope="col">COMPONENT TYPE</th><th scope="col">PLAN QTY</th><th scope="col">INSTALLED</th><th scope="col">RESERVED</th><th scope="col">FREE STOCK</th><th scope="col">SHORTAGE</th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="row in readiness" :key="row.componentId"><td>{{part(row.componentId)?.name}}<small v-if="row.blocked">{{row.blocked}} allocated units are not serviceable</small></td><td>{{row.required}}</td><td>{{row.installed}}</td><td>{{row.reserved}}</td><td>{{row.available}}</td><td :class="{'stock-shortage':row.shortage>0}">{{row.shortage}}</td><td><v-btn variant="text" color="primary" size="small" :disabled="!row.available" @click="openAllocation(undefined,selectedPC.id,row.componentId)">Allocate</v-btn></td></tr></tbody></v-table><div v-if="!readiness.length" class="empty-state"><h2>No build plan linked</h2><p>Choose a planned configuration in Edit PC & settings.</p></div></section>
      <section class="panel inventory-differences"><h2>Planned versus installed</h2><p class="form-hint">Reservations are not installed components. Slot, mount and drive role differences are tracked separately from type-level stock readiness.</p><div v-for="(difference,i) in differences" :key="i"><v-icon :icon="mdiAlertCircleOutline" size="17" />{{difference}}</div><div v-if="!differences.length"><v-icon :icon="mdiCheckCircleOutline" size="17" />Recorded hardware and build settings match the plan.</div></section>
    </template>
    <section v-if="tab==='report'" class="panel inventory-differences"><h2>Recorded slot assignments</h2><v-table data-inventory-table aria-label="Recorded expansion slot assignments"><thead><tr><th scope="col">Installed allocation</th><th scope="col">Slot</th></tr></thead><tbody><tr v-for="(slot,allocationId) in installedReport?.slotAssignments" :key="allocationId"><td>{{part(allocations.find(r=>r.allocation.id===allocationId)?.stock.componentId||'')?.name}}<small>{{allocationId}}</small></td><td>{{slot}}</td></tr></tbody></v-table><h3 class="mt-5">Resource usage</h3><v-table data-inventory-table aria-label="Installed hardware resource usage"><thead><tr><th scope="col">Resource</th><th scope="col">Used</th><th scope="col">Available</th></tr></thead><tbody><tr v-for="resource in installedReport?.resources" :key="resource.name"><td>{{resource.name}}</td><td>{{resource.used}} {{resource.unit}}</td><td>{{resource.available}} {{resource.unit}}</td></tr></tbody></v-table></section>
    <section v-if="tab==='history'" class="panel inventory-differences"><h2>PC lifecycle timeline</h2><div v-for="entry in [...(selectedPC.timeline||[])].reverse()" :key="entry.id">{{date(entry.at)}} · {{entry.kind}} · {{entry.actor}} · {{entry.summary}}</div><h3 class="mt-5">Commissioned revisions</h3><div v-for="(snapshot,index) in selectedPC.snapshots||[]" :key="snapshot.at">Revision {{index+1}} · {{date(snapshot.at)}} · {{snapshot.configuration.placements.length}} hardware records · {{snapshot.configuration.software?.os || 'OS not recorded'}}<v-btn size="small" variant="text" @click="downloadSnapshot(snapshot,index)">Download snapshot</v-btn></div></section>
    <section v-if="tab==='report'" class="panel builder-section"><div class="section-head"><div><h2>Installed compatibility: {{installedReport?.status}}</h2><p>Uses recorded installations and PC-specific settings, not template components or reservations.</p></div></div><div v-for="(finding,i) in installedReport?.findings" :key="i" :class="['finding',finding.severity]"><v-icon :icon="finding.severity==='pass'?mdiCheckCircleOutline:mdiAlertCircleOutline" size="20" /><div><strong>{{finding.title}}</strong><p>{{finding.detail}}</p></div><span>{{finding.severity==='error'?'Conflict':finding.severity==='warning'?'Review':'Pass'}}</span></div></section>
    <section v-if="tab==='history'" class="panel table-panel"><h2 class="pa-5">Component movement ledger</h2><v-table data-inventory-table aria-label="PC component movement history"><thead><tr><th scope="col">WHEN</th><th scope="col">ACTION</th><th scope="col">COMPONENT / SERIAL OR LOT</th><th scope="col">QTY</th><th scope="col">DETAILS</th></tr></thead><tbody><tr v-for="{stock,event} in movements" :key="event.id"><td>{{date(event.at)}}</td><td>{{event.action}}</td><td>{{part(stock.componentId)?.name}}<small>{{stock.serial || stock.assetTag || stock.id.slice(0,8)}}</small></td><td>{{event.quantity}}</td><td class="movement-notes">{{event.notes}}</td></tr></tbody></v-table><div v-if="!movements.length" class="empty-state"><h3>No component movements yet</h3><p>Reservations, installations, removals and placement changes will appear here.</p></div></section>
    <div class="info-callout"><v-icon :icon="mdiInformationOutline" size="19" />Changing a planned configuration does not alter installed parts or captured settings. Record physical changes with Install, Remove and Placement. Retired/quarantined components are excluded from buildable stock.</div>
  </template>

  <v-dialog :model-value="!!batch" aria-labelledby="inventory-batch-title" @keydown.esc.stop.prevent="closeDialog('batch')" max-width="720" persistent><v-card v-if="batch" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-batch-title">Batch receive stock</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close batch receiving dialog" @click="closeDialog('batch')" /></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><div class="form-grid"><v-select v-model="batch.componentId" label="Component type" :items="db.components.map(c=>({title:c.name,value:c.id}))" /><v-select v-model="batch.tracking" label="Tracking" :items="['serialized','bulk']" /><v-text-field v-model="batch.location" label="Stock location" /><v-text-field v-model="batch.supplier" label="Supplier" /><v-text-field v-model="batch.purchaseOrder" label="Purchase order" /><v-text-field v-if="batch.tracking==='bulk'" v-model.number="batch.quantity" label="Units" type="number" min="1" /></div><v-textarea v-model="batch.identities" :label="batch.tracking==='serialized'?'Serial,asset tag (one per line; scanner input supported)':'Bulk lot tag'" rows="5" /><p class="form-hint">Every row is validated and received together. A duplicate identity rejects the entire batch.</p></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('batch')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!batch.componentId||!batch.identities.trim()" @click="receiveBatch">Receive batch</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!serialization" aria-labelledby="inventory-serialization-title" @keydown.esc.stop.prevent="closeDialog('serialization')" max-width="620" persistent><v-card v-if="serialization" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-serialization-title">Assign serial numbers to bulk units</h2></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><v-textarea v-model="serialization.identities" label="Serial,asset tag (one per line)" rows="5" /><v-textarea v-model="serialization.notes" label="Reason / identity verification" rows="2" /><p class="form-hint">Only unallocated units can be converted. Quantities and movement links are preserved.</p></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('serialization')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!serialization.identities.trim()||!serialization.notes.trim()" @click="serializeLot">Convert units</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!commissioning" aria-labelledby="inventory-commissioning-title" @keydown.esc.stop.prevent="closeDialog('commissioning')" max-width="620" persistent><v-card v-if="commissioning" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-commissioning-title">Commission installed PC</h2></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><v-text-field v-model="commissioning.by" label="Verified by *" required aria-required="true" /><v-textarea v-model="commissioning.checks" label="Acceptance checks completed (one per line)" rows="4" /><v-textarea v-model="commissioning.notes" label="Acceptance notes / unresolved warnings" rows="2" /><p class="form-hint">Compatibility conflicts block commissioning. Confirm every listed check; a versioned hardware and software snapshot is retained.</p></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('commissioning')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!commissioning.by.trim()||!commissioning.checks.trim()" @click="commission">Record acceptance</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!decommissioning" aria-labelledby="inventory-decommissioning-title" @keydown.esc.stop.prevent="closeDialog('decommissioning')" max-width="680" persistent><v-card v-if="decommissioning" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-decommissioning-title">Decommission PC</h2></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><p class="form-hint">This releases all reservations and removes {{allocations.filter(r=>r.allocation.state==='installed').reduce((n,r)=>n+r.allocation.quantity,0)}} installed units. All installations use the chosen disposition and location. Review the parts list before confirming.</p><v-table data-inventory-table aria-label="Components to decommission"><thead><tr><th scope="col">Component / identity</th><th scope="col">Quantity</th><th scope="col">Allocation state</th></tr></thead><tbody><tr v-for="{stock,allocation} in allocations" :key="allocation.id"><td>{{part(stock.componentId)?.name}} · {{stock.serial||stock.assetTag}}</td><td>{{allocation.quantity}}</td><td>{{allocation.state}}</td></tr></tbody></v-table><div class="form-grid mt-5"><v-select v-model="decommissioning.disposition" label="Removed component disposition" :items="['Serviceable','Quarantined','Repair','Retired']" /><v-text-field v-model="decommissioning.location" label="Destination location" /></div><v-text-field v-model="decommissioning.actor" label="Responsible person" /><v-textarea v-model="decommissioning.notes" label="Decommissioning reason *" required aria-required="true" rows="2" /></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('decommissioning')">Cancel</v-btn><v-btn color="error" :loading="busy" :disabled="!decommissioning.location.trim()||!decommissioning.notes.trim()" @click="decommission">Remove components & retire PC</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!draft" aria-labelledby="inventory-draft-title" @keydown.esc.stop.prevent="closeDialog('draft')" max-width="720" persistent><v-card v-if="draft" class="editor-dialog"><div class="dialog-head"><div><span class="eyebrow">PHYSICAL COMPONENT STOCK</span><h2 id="inventory-draft-title">{{db.inventory.some(s=>s.id===draft?.id)?'Edit stock record':'Receive stock'}}</h2></div><v-btn :icon="mdiClose" variant="text" aria-label="Close stock editor" @click="closeDialog('draft')" /></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><div class="form-grid"><v-select v-model="draft.componentId" label="Component type *" required aria-required="true" :items="db.components.map(c=>({title:c.name,value:c.id}))" :disabled="db.inventory.some(s=>s.id===draft?.id)" /><v-select v-model="draft.tracking" label="Tracking mode" :items="['serialized','bulk']" :disabled="db.inventory.some(s=>s.id===draft?.id)" @update:model-value="draft.serial='';draft.quantity=1" /><v-text-field v-if="draft.tracking==='serialized'" v-model="draft.serial" label="Serial number *" required aria-required="true" /><v-text-field v-model="draft.assetTag" :label="draft.tracking==='bulk'?'Lot / batch tag':'Asset tag (optional)'" /><v-text-field v-model.number="draft.quantity" label="Total units" type="number" min="0" :disabled="draft.tracking==='serialized'||db.inventory.some(s=>s.id===draft?.id)" /><v-text-field v-model="draft.location" label="Home stock location" /><v-text-field v-model="draft.supplier" label="Supplier" /><v-text-field v-model="draft.purchaseOrder" label="Purchase / order reference" /><v-text-field v-model.number="draft.reorderLevel" label="Minimum free units (per component type)" type="number" min="0" /><v-text-field v-model="draft.repairReference" label="Repair / service reference" /><v-text-field v-model="draft.supplierReturnReference" label="Supplier return / RMA reference" /><v-select v-model="draft.condition" label="Condition" :items="['Serviceable','Quarantined','Repair','Retired']" /></div><v-textarea v-model="draft.notes" label="Receipt, supplier, condition or stock notes" rows="3" class="mt-5" /><div class="info-callout"><v-icon :icon="mdiInformationOutline" />A serialized unit has quantity 1 and a unique serial within its component type. Bulk quantities are individual units. Condition applies to the entire record; separate lots for different locations or conditions.</div></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('draft')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!draft.componentId||(draft.tracking==='serialized'&&!draft.serial.trim())" @click="saveStock">Save stock</v-btn></div></v-card></v-dialog>

  <v-dialog :model-value="!!operation" aria-labelledby="inventory-operation-title" @keydown.esc.stop.prevent="closeDialog('operation')" max-width="730" persistent><v-card v-if="operation" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-operation-title">{{operationTitles[operation.action]}}</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close inventory action" @click="closeDialog('operation')" /></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><template v-if="isNewAllocation"><v-select v-model="operation.stockId" label="Physical stock *" required aria-required="true" :items="stockChoices.map(s=>({title:stockLabel(s),value:s.id}))" class="mb-5" @update:model-value="resetPlacement" /><div class="form-grid"><v-select v-model="operation.pcId" label="Target PC *" required aria-required="true" :items="db.pcs.map(p=>({title:p.name,value:p.id}))" @update:model-value="resetPlacement" /><v-select v-model="operation.action" label="Action" :items="[{title:'Reserve for build',value:'reserve'},{title:'Record as installed',value:'install'}]" /></div><v-select v-model="operation.plannedPlacementId" label="Planned BOM placement (optional)" :items="[{title:'Unplanned / manually placed',value:''},...plannedLines.map(p=>({title:`${p.quantity} × ${part(p.componentId)?.name} · ${p.role} · ${p.mount}`,value:p.id}))]" class="mt-5" @update:model-value="applyPlannedPlacement" /></template><template v-else><p class="inventory-action-context">{{part(operationStock?.componentId||'')?.name}} · {{operationStock?.serial || operationStock?.assetTag || 'Bulk lot'}}<br>{{pcName(operation.pcId)}}</p></template><v-text-field v-if="operation.action!=='configure'" v-model.number="operation.quantity" :label="`Units (maximum ${operationLimit})`" type="number" min="1" :max="operationLimit" :disabled="operationStock?.tracking==='serialized'" class="my-5" /><div v-if="showPlacement" class="form-grid"><v-select v-model="operation.role" label="Recorded role" :items="roleItems" /><v-select v-model="operation.mount" label="Mount / drive access" :items="mountItems" /><v-select v-model="operation.slotId" label="Reserved / installed expansion slot" :items="slots" /><v-select v-model="operation.targetId" label="Drive target / bay" :items="driveTargets" /><v-select v-model="operation.group" label="Storage group" :items="storageGroups" /><v-select v-model="operation.adapterPlacementId" label="Drive adapter / sled" :items="providers.filter(p=>!p.value||p.category==='Storage adapter')" /><v-select v-model="operation.controllerPlacementId" label="Storage controller" :items="providers" /></div><div v-if="isNewAllocation||operation.action==='configure'" class="form-grid mt-5"><v-text-field v-model="operation.owner" label="Owner / responsible person" /><v-text-field v-model="operation.workOrder" label="Work order / purpose" /><v-text-field v-model="operation.dueAt" label="Needed by (ISO date/time)" /><v-text-field v-model="operation.expiresAt" label="Reservation expiry (ISO date/time)" /></div><div v-if="operation.action==='remove'" class="form-grid mt-5"><v-select v-model="operation.disposition" label="Returned unit disposition" :items="['Serviceable','Quarantined','Repair','Retired']" /><v-text-field v-model="operation.destinationLocation" label="Return / repair location" /></div><v-textarea v-model="operation.notes" label="Movement or service notes" rows="2" class="mt-5" /><div class="info-callout"><v-icon :icon="mdiInformationOutline" />{{operation.action==='remove'?'Removal saves the destination and condition together. Bulk units with a different condition or location receive a separate linked lot; healthy units keep their existing condition.':operation.action==='release'?'Released quantities become available again if the stock is serviceable.':operation.action==='reserve'?'Reservations reduce free stock but do not count as installed hardware.':'This records the physical state. Review installed compatibility and the planned-versus-installed report afterward.'}}</div></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('operation')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!operation.stockId||!operation.pcId||(operation.action!=='configure'&&(!Number.isInteger(operation.quantity)||operation.quantity<1||operation.quantity>operationLimit))" @click="performOperation">{{operation.action==='reserve'?'Reserve stock':operation.action==='configure'?'Save placement':'Record movement'}}</v-btn></div></v-card></v-dialog>

  <v-dialog :model-value="!!transfer" aria-labelledby="inventory-transfer-title" @keydown.esc.stop.prevent="closeDialog('transfer')" max-width="650" persistent><v-card v-if="transfer" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-transfer-title">Split or move bulk units</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close bulk transfer" @click="closeDialog('transfer')" /></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><p class="form-hint">Move unallocated units into a separate lot with its own location and condition. The source and new lot are saved together, with linked movement history.</p><div class="form-grid"><v-text-field v-model.number="transfer.quantity" label="Units to transfer" type="number" min="1" /><v-text-field v-model="transfer.assetTag" label="New lot / batch tag" /><v-text-field v-model="transfer.location" label="New stock location" /><v-select v-model="transfer.condition" label="New lot condition" :items="['Serviceable','Quarantined','Repair','Retired']" /></div><v-textarea v-model="transfer.notes" label="Transfer / condition change reason *" rows="3" class="mt-5" /></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('transfer')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!transfer.notes.trim()||!Number.isInteger(transfer.quantity)||transfer.quantity<1" @click="transferLot">Record transfer</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!adjustment" aria-labelledby="inventory-adjustment-title" @keydown.esc.stop.prevent="closeDialog('adjustment')" max-width="500" persistent><v-card v-if="adjustment" class="editor-dialog"><div class="dialog-head"><h2 id="inventory-adjustment-title">Adjust bulk count</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close count adjustment" @click="closeDialog('adjustment')" /></div><div class="dialog-body"><v-alert v-if="requestError" type="error" variant="tonal" role="alert" class="mb-5">{{requestError}}</v-alert><v-text-field v-model.number="adjustment.quantity" label="New total units (including allocations)" type="number" min="0" /><v-textarea v-model="adjustment.notes" label="Reason * (receipt, correction, damage or disposal)" rows="3" class="mt-5" /><p class="form-hint">Counts cannot fall below reserved plus installed units. The change and reason are retained in movement history.</p></div><div class="dialog-footer"><v-btn variant="text" @click="closeDialog('adjustment')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!adjustment.notes.trim()" @click="adjustCount">Record adjustment</v-btn></div></v-card></v-dialog>
</template>

